<script setup lang="ts">
import { reactive, ref } from 'vue'; import { Head, router, usePage } from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue';
const page = usePage<any>(); const form = reactive({ ...page.props.branding }); const logo = ref<File | null>(null); const favicon = ref<File | null>(null); const processing = ref(false); const designs = [{ id: 'lime', name: 'Lime Studio', color: '#d8f36a' }, { id: 'midnight', name: 'Midnight Blue', color: '#93c5fd' }, { id: 'coral', name: 'Coral Punch', color: '#fb7185' }, { id: 'ocean', name: 'Ocean Desk', color: '#67e8f9' }, { id: 'lavender', name: 'Lavender Air', color: '#c4b5fd' }, { id: 'forest', name: 'Forest Field', color: '#86efac' }, { id: 'monochrome', name: 'Mono Editorial', color: '#d6d3d1' }, { id: 'terracotta', name: 'Terracotta', color: '#fdba74' }, { id: 'royal', name: 'Royal Violet', color: '#a5b4fc' }, { id: 'sand', name: 'Sand & Ink', color: '#fde68a' }];
function save() { if (processing.value) return; const payload: Record<string, any> = { ...form }; delete payload.app_logo_path; delete payload.app_favicon_path; if (logo.value) payload.app_logo_path = logo.value; if (favicon.value) payload.app_favicon_path = favicon.value; processing.value = true; router.post('/app/settings/branding', payload, { forceFormData: true, onFinish: () => { processing.value = false; } }); }
</script>
<template><Head title="Branding"/><AppLayout><template #title>Branding</template><div class="mx-auto max-w-3xl"><form class="space-y-5 rounded-3xl border border-stone-200 bg-white p-6 shadow-sm" @submit.prevent="save"><h2 class="text-2xl font-semibold">Identitas usaha</h2><label class="block text-sm">Nama usaha<input v-model="form.app_name" class="mt-1 w-full rounded-xl border-stone-200"></label><label class="block text-sm">Alamat<textarea v-model="form.business_address" class="mt-1 w-full rounded-xl border-stone-200"></textarea></label><label class="block text-sm">Telepon<input v-model="form.business_phone" class="mt-1 w-full rounded-xl border-stone-200"></label><label class="block text-sm">Warna utama<input v-model="form.app_primary_color" type="color" class="mt-1 block h-10 w-20 rounded-xl border-stone-200"></label><fieldset><legend class="text-sm font-medium">Pilih desain interface</legend><div class="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-5"><label v-for="design in designs" :key="design.id" class="cursor-pointer rounded-xl border p-2 text-xs" :class="form.app_design === design.id ? 'border-stone-950 ring-2 ring-stone-950/10' : 'border-stone-200'"><input v-model="form.app_design" type="radio" name="app_design" :value="design.id" class="sr-only"><span class="mb-1 block h-5 rounded-md" :style="{ backgroundColor: design.color }"></span>{{ design.name }}</label></div></fieldset><label class="block text-sm">Logo<input type="file" accept="image/*" class="mt-1 block" @change="logo = ($event.target as HTMLInputElement).files?.[0] ?? null"></label><label class="block text-sm">Favicon<input type="file" accept=".ico,.png,.svg" class="mt-1 block" @change="favicon = ($event.target as HTMLInputElement).files?.[0] ?? null"></label><button :disabled="processing" class="rounded-xl bg-stone-950 px-4 py-3 font-semibold text-white disabled:opacity-50">{{ processing ? 'Menyimpan...' : 'Simpan' }}</button></form></div></AppLayout></template>
